input.contents:
const fs = require('fs');
const core = fs.readFileSync('out/html/core.js', 'utf8');
const m = core.match(/window\.game=\{"compiled":"(.+)"\}/);
const game = JSON.parse(JSON.parse('"' + m[1] + '"'));

function collectChoices(node, out) {
  if (!node || typeof node !== 'object') return;
  if (node.type === 'choice') out.push(node);
  const kids = node.content || node.choices || [];
  if (Array.isArray(kids)) kids.forEach((c) => collectChoices(c, out));
}

const hits = [];
for (const [id, scene] of Object.entries(game.scenes)) {
  const choices = [];
  collectChoices(scene.content, choices);
  for (const ch of choices) {
    const target = ch.sceneId || ch.id || ch.target;
    if (!target) continue;
    if (
      target === 'root' ||
      target.startsWith('root.') ||
      target === 'cancel_advisor_action'
    ) {
      hits.push({ sceneId: id, target, title: ch.title || ch.text || '' });
    }
  }
}
console.log(JSON.stringify(hits, null, 2));

