function listScenes(prefix) {
  return Object.keys(game.scenes).filter(k=>k.startsWith(prefix)).sort();
}

function sceneInfo(id) {
  const s = game.scenes[id];
  if (!s) return null;
  return {
    options: (s.options||[]).map(o=>o.id),
    goTo: s.goTo && s.goTo.map(g=>g.id),
    isCard: s.isCard,
    goSubStart: s.goSubStart,
    goSubEnd: s.goSubEnd,
  };
}

const cards = Object.entries(game.scenes).filter(([id,s])=>s.isCard && !s.isPinnedCard).map(([id])=>id);
console.log("cards:", cards);
for (const c of cards) {
  console.log("\n===", c, "===");
  console.log("root:", sceneInfo(c));
  const subs = listScenes(c+".");
  for (const sub of subs.slice(0,3)) console.log(sub, sceneInfo(sub));
  if (subs.length>3) console.log("...", subs.length-3, "more subs");
}
