        intraMesh: DEFAULT_INTRA_MESH,
        igHomeLinks: DEFAULT_IG_HOME_LINKS,
        assetBatches: DEFAULT_ASSET_BATCHES,
        linkParamSpec: LINK_PARAM_SPEC,
