/** Recompute Q.month_actions_remaining from reserve, limit, and used this month. */
function syncActionEconomyDisplay() {
    var limit = Number(Q.month_actions_limit)
    if (isNaN(limit) || limit < 1) { limit = 2 }
    var used = Number(Q.month_actions_used) || 0
    var reserve = Number(Q.action_reserve) || 0
    if (reserve < 0) { reserve = 0 }
    if (reserve > ACTION_RESERVE_MAX) { reserve = ACTION_RESERVE_MAX }
    Q.action_reserve = reserve
    Q.month_actions_used = used
    Q.month_actions_limit = limit
    var slotsLeft = Math.max(0, limit - used)
    Q.month_actions_remaining = Math.min(slotsLeft, reserve)
    return Q.month_actions_remaining
}

