function applySurge(Q){
  if((Q.phase||1)<2)return false;
  if((Q.phase||1)<=(Q.action_surge_granted_through_phase||0))return false;
  Q.action_surge_granted_through_phase=Q.phase;Q.action_surge_active=1;
  Q.action_reserve=(Q.action_reserve||0)+ACTION_SURGE_BONUS;
  Q.month_actions_limit=ACTION_SURGE_UNLIMITED;return true;
}
function sync(Q){
  var surge=Q.action_surge_active===1,used=Q.month_actions_used||0,reserve=Q.action_reserve||0;
  if(!surge&&reserve>ACTION_RESERVE_MAX)reserve=ACTION_RESERVE_MAX;
  Q.action_reserve=reserve;Q.month_actions_used=used;
  var limit;
  if(surge){Q.month_actions_limit=999;limit=999}
  else{limit=Q.month_actions_limit;if(isNaN(limit)||limit<1||limit>=999)limit=normalLimit(Q);Q.month_actions_limit=limit}
  Q.month_actions_remaining=surge?reserve:Math.min(Math.max(0,limit-used),reserve);
  return Q;
}
